-- Read-only audit for Supabase E2E. Do not run against production.
select ns.nspname as table_schema, cls.relname as table_name, idx.relname as index_name, pg_get_indexdef(idx.oid) as index_definition, ind.indisunique as is_unique, ind.indisprimary as is_primary, ind.indisvalid as is_valid, ind.indisready as is_ready, pg_get_expr(ind.indpred, ind.indrelid) as predicate from pg_index ind join pg_class cls on cls.oid=ind.indrelid join pg_namespace ns on ns.oid=cls.relnamespace join pg_class idx on idx.oid=ind.indexrelid where ns.nspname='public' order by cls.relname, idx.relname;
